#include "AlertManagementEngine.h"
#include "Utils.h"
#include <iostream>
#include <fstream>
#include <map>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;
namespace {struct Alert{int id=0;string severity,user,title,evidence,status,recommendation;};string csvQ(const string&s){string r="\"";for(char c:s){if(c=='\"')r+='\"';r+=c;}return r+'\"';}vector<Alert> loadAlerts(){vector<Alert>a;ifstream f("alerts.txt");string l;while(getline(f,l)){auto p=splitLine(l);if(p.size()<7)continue;try{Alert x;x.id=stoi(p[0]);x.severity=p[1];x.user=p[2];x.title=p[3];x.evidence=p[4];x.status=p[5];x.recommendation=p[6];a.push_back(x);}catch(...){}}return a;}bool saveAlerts(const vector<Alert>&a){ofstream f("alerts.txt",ios::trunc);if(!f)return false;for(auto&x:a)f<<x.id<<'|'<<cleanField(x.severity)<<'|'<<cleanField(x.user)<<'|'<<cleanField(x.title)<<'|'<<cleanField(x.evidence)<<'|'<<cleanField(x.status)<<'|'<<cleanField(x.recommendation)<<'\n';return bool(f);}}
AlertManagementEngine::AlertManagementEngine(SecurityLogger& l):logger(l){}
void AlertManagementEngine::generateAlerts(const string& actor,const string& role){auto logs=logger.readLogs();map<string,vector<string>> failed,denied,high;for(auto&f:logs){if(f.size()<6)continue;if(f[4]=="LOGIN"&&f[5].find("FAILED")==0)failed[f[2]].push_back(f[0]);if(f[4].find("RESOURCE_ACCESS")==0&&f[5].find("DENIED")==0)denied[f[2]].push_back(f[0]);if(f[4].find("RISK_ASSESSMENT")==0&&f[5].find("HIGH")!=string::npos)high[f[2]].push_back(f[0]);}auto alerts=loadAlerts();int next=1;for(auto&a:alerts)next=max(next,a.id+1);int added=0;auto exists=[&](const string& title,const string& u,const string& evidence){for(auto&a:alerts)if(a.title==title&&a.user==u&&a.evidence==evidence)return true;return false;};auto add=[&](const string&sev,const string&u,const string&t,const vector<string>&e,const string&r){string ids;for(size_t i=0;i<e.size();++i){if(i)ids+=",";ids+=e[i];}if(exists(t,u,ids))return;alerts.push_back({next++,sev,u,t,ids,"OPEN",r});++added;};for(auto&p:failed)if(p.second.size()>=3)add("HIGH",p.first,"Repeated failed logins",p.second,"Review authentication history and verify identity.");for(auto&p:denied)if(p.second.size()>=3)add("MEDIUM",p.first,"Repeated resource access denials",p.second,"Review role, resource classification and permissions.");for(auto&p:high)if(!p.second.empty())add("HIGH",p.first,"High-risk assessment observed",p.second,"Review risk factors and related events.");if(!saveAlerts(alerts)){cout<<"Could not save alerts.\n";return;}logger.logEvent(actor,role,"ALERT_GENERATION","SUCCESS_NEW_"+to_string(added));cout<<"Alert generation complete. New alerts: "<<added<<". Total saved alerts: "<<alerts.size()<<"\n";}
void AlertManagementEngine::viewAlerts()const{auto a=loadAlerts();if(a.empty()){cout<<"No alerts saved. Generate alerts first.\n";return;}cout<<"\n===== ALERT REGISTER =====\n";for(auto&x:a)cout<<"ID: "<<x.id<<" | "<<x.severity<<" | "<<x.status<<" | "<<x.user<<" | "<<x.title<<"\nEvidence: "<<x.evidence<<"\nAction: "<<x.recommendation<<"\n--------------------------\n";}
void AlertManagementEngine::updateAlert(const string& actor,const string& role){auto a=loadAlerts();if(a.empty()){cout<<"No alerts to update.\n";return;}int id;cout<<"Alert ID: ";if(!(cin>>id)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid ID.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');auto it=find_if(a.begin(),a.end(),[&](auto&x){return x.id==id;});if(it==a.end()){cout<<"Alert not found.\n";return;}int c;cout<<"1.OPEN 2.ACKNOWLEDGED 3.INVESTIGATING 4.RESOLVED\nChoice: ";if(!(cin>>c)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid choice.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');const string s[]={"","OPEN","ACKNOWLEDGED","INVESTIGATING","RESOLVED"};if(c<1||c>4){cout<<"Invalid status.\n";return;}it->status=s[c];if(!saveAlerts(a)){cout<<"Could not save alert.\n";return;}logger.logEvent(actor,role,"ALERT_STATUS","SUCCESS_ALERT_"+to_string(id)+"_"+it->status);cout<<"Alert status updated.\n";}
void AlertManagementEngine::exportAlerts()const{auto a=loadAlerts();ofstream t("alert_report.txt",ios::trunc);ofstream c("alert_report.csv",ios::trunc);if(!t||!c){cout<<"Could not create reports.\n";return;}t<<"VIGILX ALERT REGISTER\nAlerts are heuristic findings, not confirmed attacks.\n\n";c<<"AlertID,Severity,Username,Title,EvidenceEventIDs,Status,Recommendation\n";for(auto&x:a){t<<x.id<<" | "<<x.severity<<" | "<<x.status<<" | "<<x.user<<" | "<<x.title<<"\nEvidence: "<<x.evidence<<"\nRecommended action: "<<x.recommendation<<"\n\n";c<<x.id<<','<<csvQ(x.severity)<<','<<csvQ(x.user)<<','<<csvQ(x.title)<<','<<csvQ(x.evidence)<<','<<csvQ(x.status)<<','<<csvQ(x.recommendation)<<'\n';}cout<<"Saved alert_report.txt and alert_report.csv.\n";}
void AlertManagementEngine::runMenu(const string&u,const string&r){if(r!="Admin"&&r!="SecurityAnalyst"){cout<<"Access denied.\n";logger.logEvent(u,r,"ALERT_MANAGEMENT","DENIED_NOT_AUTHORIZED");return;}int c;do{cout<<"\n===== ALERT MANAGEMENT =====\n1. Generate Alerts from Logs\n2. View Alert Register\n3. Update Alert Status\n4. Export TXT/CSV Reports\n0. Return\nChoice: ";if(!(cin>>c)){cin.clear();cin.ignore(100000,'\n');cout<<"Invalid input.\n";continue;}cin.ignore(100000,'\n');switch(c){case 1:generateAlerts(u,r);break;case 2:viewAlerts();break;case 3:updateAlert(u,r);break;case 4:exportAlerts();break;case 0:break;default:cout<<"Invalid choice.\n";}}while(c!=0);}
